const D = { energy: .55, scale: 1, density: .55, speed: 1, growth: .55, hue: 96, x: .5, y: .68, style: 'reclaimed', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A dead factory across a flooded yard, being taken back. Composed as a FRONTAL
// ELEVATION in five planes — foreground scrub / standing water + reflection / the shell /
// more shells behind it / sky — not a one-point receding hall (that is world.machine_hall's
// skeleton and cloning it would be pointless). The window openings are a grid of black voids:
// the segmentation IS the building. Birch has taken the roofline, the water holds the whole
// thing upside down and keeps tearing it up, and the light walks across the facade. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }   // >>> : a >> fold caps the hash at 0.5
function fr(i){ return hsh((i*7+13)|0, (i*31+5)|0); }
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), gro = cl(P.growth,0,1);
const Hh = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', win = sty==='winter', noc = sty==='nocturne', xr = sty==='xray';

// ---- palette ----
let skyT, skyH, wallD, wallL, voidC, leafC, hazeC;
if (bp)       { skyT=[214,72,14]; skyH=[204,50,30]; wallD=[200,58,20]; wallL=[188,40,72]; voidC=[216,80,7];  leafC=[186,46,60]; hazeC=[202,44,34]; }
else if (win) { skyT=[216,16,58]; skyH=[214,10,76]; wallD=[210,10,30]; wallL=[206,6,72];  voidC=[220,26,9];  leafC=[24,22,44];  hazeC=[212,8,72]; }
else if (noc) { skyT=[228,52,20]; skyH=[222,40,40]; wallD=[218,26,13]; wallL=[212,16,44]; voidC=[230,60,4];  leafC=[Hh+20,30,22]; hazeC=[220,30,36]; }
else if (xr)  { skyT=[210,36,8];  skyH=[206,28,16]; wallD=[196,20,22]; wallL=[180,8,86];  voidC=[204,30,4];  leafC=[176,14,66]; hazeC=[196,18,30]; }
else          { skyT=[Hh+112,22,44]; skyH=[Hh+96,14,68]; wallD=[Hh+40,10,24]; wallL=[Hh+34,12,62]; voidC=[Hh+130,40,6]; leafC=[Hh-6,52,44]; hazeC=[Hh+90,10,62]; }

const wln = cl(P.y,.42,.88), wl = wln*height;          // the waterline across the yard
const sc = cl(P.scale,.5,2.2);

// ---- perpetual drift: monotonic, guarded against a t0 reset ----
if (S.dr == null) S.dr = 0;
if (S.lt == null || K.t < S.lt) S.lt = K.t;
const dt = cl(K.t - S.lt, 0, .1); S.lt = K.t;
S.dr += dt * P.speed * (.020 + .020*K.intensity) * (.85 + .15*Math.sin(tt*.039));
const dr = S.dr;
// the light walking across the facade on two incommensurate rates — re-lights the whole
// elevation over 8s even though the building itself never moves
const lgt = .34*Math.sin(tt*.047) + .15*Math.sin(tt*.113+1.1);
const lightX = cl(P.x + lgt, -.3, 1.3);
const lightB = (.42+en*.75)*(.80 + .12*Math.sin(tt*.071) + .08*Math.sin(tt*.163+2.2) + K.swell*.10);

const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(64, Math.round(BW*height/width));
if (!S.g || S.bk !== BW+'x'+BH){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BW,BH); S.g.pixelDensity(1); S.bk = BW+'x'+BH; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const cT = hsv(skyT[0], skyT[1]/100, skyT[2]/100);
const cH = hsv(skyH[0], skyH[1]/100, skyH[2]/100);
const cWd = hsv(wallD[0], wallD[1]/100, wallD[2]/100);
const cWl = hsv(wallL[0], wallL[1]/100, wallL[2]/100);
const cV = hsv(voidC[0], voidC[1]/100, voidC[2]/100);
const cLf = hsv(leafC[0], leafC[1]/100, leafC[2]/100);
const cHz = hsv(hazeC[0], hazeC[1]/100, hazeC[2]/100);

// ---- the shells: plane 0 = far (small, hazed), plane 1 = the hero ----
// Each is a block with a roofline, a window grid, and growth on every ledge.
const SH = [];
const nFar = 3 + Math.round(cl(P.density,0,1)*4);
for (let i=0;i<nFar;i++){
  const f1 = fr(i*9+41), f2 = fr(i*9+42), f3 = fr(i*9+43);
  SH.push({ dep:.62+f3*.30, cx:(f1*1.5-.25) + dr*.06, w:.12+f2*.20, h:.10+f3*.16,
            cols:3+Math.floor(f1*5), rows:2+Math.floor(f2*3), ph:i*17.3, hero:0 });
}
SH.push({ dep:.10, cx:cl(P.x,0,1)*.5+.25 + dr*.11, w:.46*sc, h:.34*sc,
          cols:7+Math.floor(fr(3)*5), rows:3+Math.floor(fr(5)*2), ph:3.7, hero:1 });
SH.sort((a,b)=>b.dep-a.dep);                      // far first, hero last (drawn over)

// roofline: broken, with birch standing on it
function roofY(nx, B){
  const rel = (nx - B.cx)/Math.max(.01,B.w);
  if (Math.abs(rel) > .5) return 2;               // outside the block
  const base = wln - B.h;
  // collapse: bites taken out of the parapet
  const col = fbm(rel*3.1 + B.ph, B.ph*.7);
  const bite = cl((col-.52)*3.4,0,1)*B.h*.34;
  const saw = Math.abs(((rel*(B.cols*.5)+.5)%1)-.5);   // sawtooth north-light roof
  return base + bite + saw*B.h*.10;
}

for (let j=0;j<BH;j++){
  const ny = (j+.5)/BH;
  for (let i=0;i<BW;i++){
    const nx = (i+.5)/BW;
    let r,g2,b2;
    // ---------- sky ----------
    const sv = Math.pow(cl(ny/wln,0,1), 1.3);
    r = cT[0]+(cH[0]-cT[0])*sv; g2 = cT[1]+(cH[1]-cT[1])*sv; b2 = cT[2]+(cH[2]-cT[2])*sv;
    const cf = fbm(nx*2.9 + tt*.058, ny*5.1 + tt*.034);
    const deck = cl((cf-.42)*2.4,0,1)*cl(1-ny/wln*.3,0,1);
    r += (cH[0]*1.18-r)*deck*.32*lightB; g2 += (cH[1]*1.18-g2)*deck*.32*lightB; b2 += (cH[2]*1.18-b2)*deck*.32*lightB;

    // ---------- shells (frontal elevation, far -> near) ----------
    // sample point: above the waterline directly, or MIRRORED if we are in the water
    const inWater = ny > wln;
    const dw = inWater ? (ny-wln)/Math.max(.03,1-wln) : 0;
    // the reflection tears: broad sliding bands, and they are what keep the water alive
    const rp = inWater ? (fbm(nx*6.0 + tt*.19, ny*38 - tt*.55)-.5)*(.022+dw*.155)
                       + Math.sin(ny*120*(1+dw) - tt*1.7 + nx*2.6)*(.003+dw*.020) : 0;
    const sy = inWater ? cl(wln - (ny-wln)*(.62+dw*.22) + rp, 0, wln) : ny;

    let er=r, eg=g2, eb=b2;                        // the elevation colour at sy
    for (let k=0;k<SH.length;k++){
      const B = SH[k];
      const rel = (nx-B.cx)/Math.max(.01,B.w);
      if (Math.abs(rel) > .5) continue;
      const ry = roofY(nx, B);
      if (sy < ry || sy > wln+.001) continue;
      // --- inside the shell's elevation ---
      const vv = (wln - sy)/Math.max(.01,B.h);     // 0 at the water, 1 at the parapet
      // window grid: THE segmentation. Openings are voids — the interior is dark.
      const gx = (rel+.5)*B.cols, gy = vv*B.rows;
      const fx2 = Math.abs((gx%1)-.5), fy2 = Math.abs((gy%1)-.5);
      const opening = (fx2 < .33 && fy2 < .32) ? 1 : 0;
      const wq = fr(Math.floor(gx)*13 + Math.floor(gy)*7 + k*101);
      // masonry: raking light from lightX + grime running down from every sill
      const rake = cl(1 - Math.abs(nx-lightX)*1.5, 0, 1);
      const grime = fbm(rel*14 + B.ph, vv*5.5)*.5 + fbm(rel*40, vv*30)*.5;
      let lum = .30 + rake*(.40+en*.34)*lightB + (grime-.5)*.30;
      lum *= 1 - cl((1-vv)*.5,0,1)*.18;            // damp rising up the wall from the water
      let cr = cWd[0]+(cWl[0]-cWd[0])*cl(lum,0,1);
      let cg = cWd[1]+(cWl[1]-cWd[1])*cl(lum,0,1);
      let cb = cWd[2]+(cWl[2]-cWd[2])*cl(lum,0,1);
      if (opening){
        // a void. A few still hold glass, and those catch the sky.
        const glass = wq > .80 ? 1 : 0;
        if (glass){
          const gl = cl(.30+rake*.9,0,1)*lightB;
          cr = cH[0]*gl*.8+cV[0]*.3; cg = cH[1]*gl*.8+cV[1]*.3; cb = cH[2]*gl*.9+cV[2]*.3;
        } else {
          const depth = .10 + wq*.18;
          cr = cV[0]*(1+depth); cg = cV[1]*(1+depth); cb = cV[2]*(1+depth);
          // growth spilling out of the opening
          const sp = cl((fbm(gx*5+k, gy*5)-.5)*3.0,0,1)*gro*cl(1-fy2*3,0,1);
          cr += (cLf[0]*.5-cr)*sp*.6; cg += (cLf[1]*.5-cg)*sp*.6; cb += (cLf[2]*.5-cb)*sp*.6;
        }
      }
      // ivy climbing the facade: dense at the base, thinning upward, stirring in the wind
      const ivy = cl((fbm(rel*5.5 + B.ph*.3 + Math.sin(tt*.21+B.ph)*.055,
                          vv*4.2 - dr*.05) - (.30 + vv*.46))*4.2, 0, 1) * gro;
      const ivyL = cl(.35 + rake*.5, 0, 1);
      cr += (cLf[0]*(.5+ivyL*.8)-cr)*ivy*.86; cg += (cLf[1]*(.5+ivyL*.8)-cg)*ivy*.86;
      cb += (cLf[2]*(.5+ivyL*.8)-cb)*ivy*.86;
      // aerial perspective on the far shells
      const ha = cl(B.dep*B.dep*1.05, 0, .90);
      er = cr+(cHz[0]-cr)*ha; eg = cg+(cHz[1]-cg)*ha; eb = cb+(cHz[2]-cb)*ha;
      break;
    }
    if (!inWater){ r = er; g2 = eg; b2 = eb; }
    else {
      // ---------- standing water: the elevation, upside down and torn ----------
      // fresnel: mirror at the far bank, dead and dark underfoot
      const fres = (1-dw*.55)*(.62+en*.14);
      r = er*fres; g2 = eg*fres; b2 = eb*fres;
      // the water body itself has a colour (silt, algae) that the reflection sits in
      r += (cLf[0]*.16-r)*(.20+dw*.30); g2 += (cLf[1]*.20-g2)*(.20+dw*.30); b2 += (cLf[2]*.16-b2)*(.20+dw*.30);
      // wind chop catching the sky — broad, live, everywhere
      const ch = Math.pow(cl(fbm(nx*11 + tt*.31, ny*60 - tt*.9),0,1), 2.2);
      const spk = ch*(.10+dw*.46)*(.30+en*.9);
      r += cH[0]*spk*.95; g2 += cH[1]*spk*.95; b2 += cH[2]*spk*.95;
    }
    const o = 4*(j*BW+i);
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255); px[o+3]=255;
  }
}
g.updatePixels();
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(g,0,0,width,height);
pop();

const AL = P.alpha/100;
const dens = cl(P.density,0,1);

// ---- birch standing on the roofline: the reclamation, in silhouette ----
push();
const NT = Math.round(3 + dens*14);
for (let i=0;i<NT;i++){
  const f1 = fr(i*6+201), f2 = fr(i*6+202), f3 = fr(i*6+203);
  const B = SH[SH.length-1];
  const rel = (f1-.5)*.94;
  const bx = (B.cx + rel*B.w);
  const by = (wln - B.h + fbm(rel*3.1+B.ph, B.ph*.7)*0 ) * height;
  const th = u*(.05+f2*.12)*sc*gro;
  const sw = Math.sin(tt*(.5+f3*.9)+f1*6.28)*(.010+f2*.022)*(.3+en);
  stroke(leafC[0], leafC[1]*.5, leafC[2]*.45, 78*AL);
  strokeWeight(Math.max(.6, th*.035));
  noFill();
  line(bx*width, by, bx*width+sw*width, by-th);
  // crown: a few tufts, stirring
  noStroke();
  for (let k=0;k<4;k++){
    const q = fr(i*13+k);
    fill(leafC[0]+q*20, leafC[1]*(.7+q*.5), leafC[2]*(.6+q*.7), 56*AL);
    ellipse(bx*width + sw*width*(.6+k*.2) + (q-.5)*th*.42,
            by - th*(.62+k*.12) + Math.sin(tt*(.7+q)+k)*th*.02,
            th*(.20+q*.20), th*(.14+q*.14));
  }
}
pop();

// ---- foreground scrub along the bottom edge: the nearest plane, in near-silhouette ----
push();
noStroke();
const NS = Math.round(14 + dens*70);
for (let i=0;i<NS;i++){
  const f1 = fr(i*4+301), f2 = fr(i*4+302), f3 = fr(i*4+303);
  const sx = (f1*1.14-.07)*width;
  const dep = f2;
  const syy = height*(1.03 - Math.pow(1-dep,2.2)*.13);
  const sh2 = u*(.05+dep*.26)*sc;
  const sw = Math.sin(tt*(.6+f3*1.3)+f1*6.28)*(.06+f3*.20)*(.3+en*.9)
           + Math.sin(tt*(1.7+f2*1.1)+f2*6.28)*(.03+f3*.07);
  fill(leafC[0]-8, leafC[1]*(.5+f3*.4), leafC[2]*(.14+dep*.24), (80+dep*18)*AL);
  beginShape();
  vertex(sx-sh2*.05, syy);
  vertex(sx+sh2*.05, syy);
  vertex(sx+sw*sh2*.5, syy-sh2);
  endShape(CLOSE);
}
pop();

// ---- mist crossing the yard, and a bird off the roofline ----
push();
noStroke();
for (let i=0;i<6;i++){
  const f1 = fr(i*5+401), f2 = fr(i*5+402);
  const vx = ((f1 + tt*(.005+f2*.011)*P.speed) % 1.4 - .2)*width;
  fill(hazeC[0], hazeC[1]*.8, hazeC[2], (6+en*8)*AL);
  ellipse(vx, wl - height*(.02+f2*.20) + Math.sin(tt*(.08+f1*.14))*height*.008,
          width*(.28+f1*.44), height*(.020+f2*.05));
}
const NBird = Math.round(dens*4);
for (let i=0;i<NBird;i++){
  const f1 = fr(i*7+501), f2 = fr(i*7+502);
  const ax = .5 + .38*Math.sin(tt*(.043+f1*.05)+f1*6.28) + .12*Math.sin(tt*(.101+f2*.03));
  const ay = .22 + .14*Math.sin(tt*(.061+f2*.04)+f2*6.28);
  const bs = u*.005*(.5+f2)*sc;
  const flap = Math.sin(tt*(3.4+f1*2.1)+f2*6.28)*.6;
  fill(skyT[0], skyT[1]*.6, skyT[2]*.5, 58*AL);
  beginShape();
  vertex(ax*width-bs, ay*height - bs*flap*.8); vertex(ax*width, ay*height);
  vertex(ax*width+bs, ay*height - bs*flap*.8); vertex(ax*width, ay*height + bs*.2);
  endShape(CLOSE);
}
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
drawingContext.globalAlpha = 1;
